  })

  it('já inscrito mostra a inscrição existente e clicar em Cancelar envia POST /inscricoes/:id/cancelamento', async () => {
    const { falsa, api, container } = montar()
    const inscrita = {
      id: 'ins_7f8a9b0c',
      atividadeId: 'atv_c3d4e5f6',
